css:
/* --- 组件核心样式 (无背景依赖) --- */

/* 1. 开关主容器 */
.reactor-switch {
  position: relative;
  display: inline-block; /* 确保不占满整行 */
  width: 160px;
  height: 64px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  /* 使用 drop-shadow 替代 box-shadow 处理外部投影，
     这样在透明或复杂背景上边缘更自然 */
  filter: drop-shadow(0 10px 15px rgba(0, 0, 0, 0.2));
}

/* 隐藏原生 Checkbox */
.reactor-input {
  display: none;
}

/* 2. 金属外壳 (Casing) */
.reactor-casing {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  /* 自身材质颜色：深钛金 */
  background: linear-gradient(180deg, #3a3f4b, #1e2025);
  border-radius: 40px;
  /* 内部光影结构 */
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.2),
    inset 0 -3px 0 rgba(0, 0, 0, 0.4),
    0 0 0 2px #1e2025; /* 自身描边，防止在深色背景混淆 */

  /* 叠加拉丝金属纹理 */
  background-image: repeating-linear-gradient(
      90deg,
      rgba(255, 255, 255, 0) 0px,
      rgba(255, 255, 255, 0.02) 1px,
      rgba(255, 255, 255, 0) 2px
    ),
    linear-gradient(180deg, #3a3f4b, #1e2025);

  padding: 6px;
  transition: box-shadow 0.3s ease;
  z-index: 1;
}

/* 3. 内部轨道 (Track) */
.reactor-track {
  position: relative;
  width: 100%;
  height: 100%;
  background: #0a0a0a; /* 轨道底色 */
  border-radius: 30px;
  box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.6);
  overflow: hidden;
}

/* 轨道网格装饰 */
.reactor-track::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image: linear-gradient(
    90deg,
    rgba(255, 255, 255, 0.03) 1px,
    transparent 1px
  );
  background-size: 10px 100%;
  opacity: 0.5;
}

/* 等离子光束 */
.plasma-beam {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 0%;
  background: linear-gradient(90deg, rgba(0, 242, 255, 0.6), #00f2ff);
  opacity: 0.5;
  filter: blur(8px); /* 辉光滤镜 */
  transition:
    width 0.5s cubic-bezier(0.7, 0, 0.3, 1),
    opacity 0.4s ease;
}

/* 4. 机械滑块 (Slider) */
.reactor-slider {
  position: absolute;
  top: 6px;
  left: 6px;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: linear-gradient(145deg, #444, #222);
  /* 自身的立体阴影 */
  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, 0.3),
    0 2px 5px rgba(0, 0, 0, 0.5),
    0 0 0 1px #000;
  transition: transform 0.5s cubic-bezier(0.7, 0, 0.3, 1);
  z-index: 2;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* 散热纹理 */
.slider-vents {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  border-radius: 50%;
  border: 4px solid transparent;
  border-top-color: rgba(255, 255, 255, 0.1);
  border-bottom-color: rgba(0, 0, 0, 0.3);
  transform: rotate(45deg);
}

/* 5. 能量核心 (Core) */
.reactor-core {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: #111;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.8);
  position: relative;
  overflow: hidden;
}

/* 核心内部 */
.core-inner {
  position: absolute;
  top: 3px;
  left: 3px;
  right: 3px;
  bottom: 3px;
  background: #333;
  border-radius: 50%;
  transition: all 0.5s ease;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.5);
}

/* =========================================
   交互状态：开启 (Checked)
   ========================================= */

/* 1. 滑块移动 */
.reactor-input:checked ~ .reactor-casing .reactor-slider {
  transform: translateX(96px); /* 160 - 64 = 96 */
}

/* 2. 激活光束 */
.reactor-input:checked ~ .reactor-casing .plasma-beam {
  width: 100%;
  opacity: 1;
  animation: beam-pulse 1.5s infinite alternate;
}

/* 3. 核心点火 */
.reactor-input:checked ~ .reactor-casing .reactor-slider .core-inner {
  background: #fff;
  box-shadow:
    0 0 10px #00f2ff,
    0 0 20px #00f2ff,
    inset 0 0 5px #00f2ff;
}

/* 4. 核心旋转 */
.reactor-input:checked ~ .reactor-casing .reactor-slider .reactor-core {
  animation: core-spin 2s linear infinite;
  border-color: rgba(0, 242, 255, 0.5);
}

/* 5. 外壳环境光反射 */
.reactor-input:checked ~ .reactor-casing {
  /* 增加蓝色外发光，模拟能量溢出 */
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.2),
    0 0 25px rgba(0, 242, 255, 0.2);
}

/* --- 关键帧动画 --- */
@keyframes beam-pulse {
  0% {
    opacity: 0.8;
    filter: blur(6px);
  }
  100% {
    opacity: 1;
    filter: blur(9px);
    box-shadow: 0 0 15px #00f2ff;
  }
}

@keyframes core-spin {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

/* --- 触摸反馈 --- */
.reactor-switch:active .reactor-slider {
  transform: scale(0.96);
}
.reactor-input:checked:active ~ .reactor-casing .reactor-slider {
  transform: translateX(96px) scale(0.96);
}
